'use client'

// TEMPORARY debug harness — delete after verifying RTL alignment.
import { RichTextEditor } from '@mantine/tiptap'
import LinkExtension from '@tiptap/extension-link'
import Placeholder from '@tiptap/extension-placeholder'
import TextAlign from '@tiptap/extension-text-align'
import Underline from '@tiptap/extension-underline'
import StarterKit from '@tiptap/starter-kit'
import { useEditor } from '@tiptap/react'
import { useState } from 'react'

export default function AlignTest() {
  const [html, setHtml] = useState('')
  const editor = useEditor({
    immediatelyRender: false,
    extensions: [
      StarterKit.configure({
        heading: false,
        blockquote: false,
        code: false,
        codeBlock: false,
        horizontalRule: false,
        strike: false,
      }),
      Underline,
      TextAlign.configure({ types: ['paragraph'] }),
      LinkExtension.configure({ autolink: true, openOnClick: false, defaultProtocol: 'https' }),
      Placeholder.configure({ placeholder: 'test' }),
    ],
    content: '<p>نص عربي للاختبار</p>',
    onUpdate: ({ editor }) => setHtml(editor.getHTML()),
  })

  return (
    <div style={{ padding: 24 }}>
      <RichTextEditor editor={editor} id="test-editor">
        <RichTextEditor.Toolbar>
          <RichTextEditor.ControlsGroup>
            <RichTextEditor.AlignLeft />
            <RichTextEditor.AlignCenter />
            <RichTextEditor.AlignRight />
          </RichTextEditor.ControlsGroup>
        </RichTextEditor.Toolbar>
        <RichTextEditor.Content id="test-content" />
      </RichTextEditor>
      <pre id="test-html" style={{ marginTop: 16, fontSize: 12 }}>{html}</pre>
    </div>
  )
}
